head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf35023";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — item

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf35023.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const array = [(String(((dma_pageContext.get("item") ?? "")) === null ? '' : ((dma_pageContext.get("item") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("item") ?? "")) === null ? '' : ((dma_pageContext.get("item") ?? ""))))];
        scwin.setParamFromParent(array);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf35023.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf35023.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf35023.btn_mpd_files_del_onclick' }); }
};

/**
 * @method
 * @name btn_fileBrowse_onclick
 * @description btn_fileBrowse 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fileBrowse_onclick = function(e){
    try {
        $c.util.onUploadClick($c.util.getComponent('mpd_files'))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf35023.btn_fileBrowse_onclick' }); }
};

/**
 * @method
 * @name btn_delRow_onclick
 * @description btn_delRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_delRow_onclick = function(e){
    try {
        fn_delRow()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf35023.btn_delRow_onclick' }); }
};

/**
 * @method
 * @name aLinkUpload_onclick
 * @description aLinkUpload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.aLinkUpload_onclick = async function(e){
    try {
        await scwin.doSave()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf35023.aLinkUpload_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf35023.btn_self_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_doSave
 * @description do Save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_doSave = async function () {
    const sbmOptions = {
        id: "tx_doSave",
        method: "post",
        action: "/upload/uploadFile.do",
        ref: "dma_doSaveReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParamFromParent
 * @description set Param From Parent 처리
 * @param {Array} arr arr
 * @returns {void}
 * @hidden N
 */
scwin.setParamFromParent = function (arr) {
    for (let i = 0; i < arr.length; i++) {
        $("#inputContainer").append("<input type='hidden' name='bnd_appl_id_list' value='" + arr[i] + "'>");
    }
};

/**
 * @method
 * @name doSave
 * @description do Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doSave = async function () {
    const fm = (document.SendForm || { elements: [] });
    if (rownum < 1) {
        await $c.win.alert("업로드 할 대상이 없습니다.");
        return;
    }
    const fileYn = 'N';
    if (rownum > 0) {
        for (let i = 0; i < rownum; i++) {
            let temp;
            if (rownum === 1) {
                temp = fm.attach_file_tp_cd.value;
            } else {
                temp = fm.attach_file_tp_cd[i].value;
            }
            if ($("input[name='attach_file_nm[" + i + "]']").val() === "") {
                await $c.win.alert("파일을 선택하십시오.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            if (temp === "") {
                await $c.win.alert("첨부된 파일의 구분을 선택하십시오.");
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    if (!await $c.win.confirm("업로드하시겠습니까?")) {
        return;
    }
    $c.util.getComponent('txt_spanUpload').setLabel("업로드 중...");
    $("#aLinkUpload").attr("onclick", "return false;");
    fm.action = '/upload/uploadFile.do';
    $c.util.getComponent('dma_doSaveReq').set('method', 'saveUploadFile');
    await scwin.tx_doSave();
};
